// The builder's pull requests on GitHub, through the GitHub CLI: found by
// their branch (open, merged or closed), opened (as a draft when the checks
// fail), changed, and everything said on one (its comments, its reviews
// and the comments on its lines), oldest first. The description shows the
// screenshots the branch adds.
import { existsSync } from "node:fs";
import { basename, extname, join } from "node:path";
import { answer } from "../add-ons/github/board-setup.js";
import { branchOf } from "./branches.js";
import { changedFiles } from "./checks.js";
const PICTURE = /\.(png|jpe?g|gif|webp)$/i;
const MOST_PICTURES = 12;
// What the owner says on a clashing pull request (Resolve on its card): the
// builder answers it like any review, bringing in main and settling the
// clash in its next round.
export const RESOLVE_ASK = "Please bring in the latest main and resolve the merge conflicts, keeping what both sides meant.";
export function githubPullRequests(cli, repository) {
    const gh = async (args) => answer(await cli.run(args));
    const json = async (args) => JSON.parse(await gh(args));
    const repo = ["--repo", repository];
    const find = async (branch) => {
        const found = await json([
            "pr",
            "list",
            ...repo,
            "--head",
            branch,
            "--state",
            "all",
            "--json",
            "number,url,state,isDraft,mergeable",
        ]);
        const first = found[0];
        return first
            ? {
                number: first.number,
                url: first.url,
                state: first.state,
                draft: first.isDraft,
                conflicting: first.mergeable === "CONFLICTING",
            }
            : null;
    };
    return {
        repository,
        baseBranch: () => defaultBranch(gh, repository),
        find,
        open: async (opening) => {
            await gh(createArgs(repo, opening));
            const made = await find(opening.branch);
            if (!made)
                throw new Error("GitHub did not show the new pull request.");
            return made;
        },
        update: async (number, body, draft) => {
            if (body !== null)
                await gh(["pr", "edit", String(number), ...repo, "--body", body]);
            await gh([
                "pr",
                "ready",
                String(number),
                ...repo,
                ...(draft ? ["--undo"] : []),
            ]).catch(() => "");
        },
        comment: async (number, text) => {
            await gh(["pr", "comment", String(number), ...repo, "--body", text]);
        },
        said: (number) => saidOn(json, repository, number),
    };
}
async function defaultBranch(gh, repository) {
    const name = await gh([
        "repo",
        "view",
        repository,
        "--json",
        "defaultBranchRef",
        "--jq",
        ".defaultBranchRef.name",
    ]);
    return name.trim() || "main";
}
function createArgs(repo, opening) {
    return [
        "pr",
        "create",
        ...repo,
        "--head",
        opening.branch,
        "--base",
        opening.base,
        "--title",
        opening.title,
        "--body",
        opening.body,
        ...(opening.draft ? ["--draft"] : []),
    ];
}
// Everything said on a pull request, oldest first.
async function saidOn(json, repository, number) {
    const viewed = await json([
        "pr",
        "view",
        String(number),
        "--repo",
        repository,
        "--json",
        "comments,reviews",
    ]);
    const lines = await json(["api", `repos/${repository}/pulls/${String(number)}/comments`]);
    const message = (author, body, at) => ({
        author: author?.login ?? "",
        body,
        at,
        where: "pull request",
    });
    return [
        ...viewed.comments.map((c) => message(c.author, c.body, c.createdAt)),
        ...viewed.reviews
            .filter((r) => r.body.trim() !== "")
            .map((r) => message(r.author, r.body, r.submittedAt)),
        ...lines.map((c) => message(c.user, c.path ? `(${c.path}) ${c.body}` : c.body, c.created_at)),
    ].sort((a, b) => a.at.localeCompare(b.at));
}
// The pictures the branch adds (the screenshots of its run), at most a
// dozen: shown in the description, since a picture only named in it is one
// nobody opens.
async function picturesIn(copy, base) {
    return (await changedFiles(copy, base))
        .filter((file) => PICTURE.test(file) && existsSync(join(copy, file)))
        .slice(0, MOST_PICTURES);
}
// The description's pictures, each shown from the branch on GitHub.
export function picturesSection(pictures, repository, branch) {
    if (pictures.length === 0 || repository === "")
        return "";
    const shown = pictures.map((file) => `![${basename(file, extname(file))}](https://github.com/${repository}/blob/${branch}/${file}?raw=true)`);
    return `\n\n## Screenshots\n\n${shown.join("\n\n")}`;
}
// Opens the card's pull request, or updates the one there is; its address.
export async function openOrUpdate(pullRequests, card, text, draft, at) {
    const branch = branchOf(card.number);
    const base = await pullRequests.baseBranch();
    const pictures = at ? await picturesIn((await at.build()).path, base) : [];
    const shown = picturesSection(pictures, pullRequests.repository ?? "", branch);
    const body = `${text}${shown}\n\nCloses #${String(card.number)}.`;
    const found = await pullRequests.find(branch);
    if (found?.state === "OPEN") {
        await pullRequests.update(found.number, body, draft);
        return found.url;
    }
    const made = await pullRequests.open({
        branch,
        base,
        title: card.title,
        body,
        draft,
    });
    return made.url;
}
